{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "command": "astryx experimental icon new-set",
    "description": "[experimental] Start an icon set in your integration package",
    "usage": "astryx experimental icon new-set [options] <name>",
    "options": [
      {
        "flags": "--dry-run",
        "description": "Validate and show planned writes without changing files"
      },
      {
        "flags": "--from <module>",
        "description": "A module whose every icon component the set wraps (a package, a subpath, or a ./ path); run again to refresh"
      },
      {
        "flags": "--exclude <names>",
        "description": "With --from: comma-separated export names of the library that are not icons"
      },
      {
        "flags": "--variants <list>",
        "description": "Comma-separated variants the set supplies, such as outline,solid"
      },
      {
        "flags": "--default-variant <variant>",
        "description": "With --variants: the variant each icon's own export draws. When omitted: in a library whose export names encode looks, the look the icons draw (the library's usual default for a new set), which --variants must list; otherwise the set's current default, which --variants must list when the set has icons, else, on a set without icons, the first variant. A set with icons changes it only with --from, and only in a library whose export names encode looks"
      },
      {
        "flags": "--display-name <text>",
        "description": "The set's display name (the name in title case when omitted)"
      },
      {
        "flags": "--description <text>",
        "description": "The set's one-line description"
      }
    ],
    "subcommands": []
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
